import logging

logger = logging.getLogger(__name__)


def reset_password(email: str, new_password: str, set_password) -> bool:
    if len(new_password) < 8:
        logger.warning("Password reset for %s rejected: new password is too short", email)
        raise ValueError("new password is too short")
    changed = bool(set_password(email, new_password))
    if changed:
        logger.info("Password for %s updated", email)
    else:
        logger.info("Password reset for %s ignored: unknown account", email)
    return changed

